import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:pulse/data/card_combos.dart';

Map<String, dynamic> _json(String path) =>
    jsonDecode(File(path).readAsStringSync()) as Map<String, dynamic>;

/// The shipped combos are generated by the backend (`pulse` repo,
/// `scripts/export_app_combos.py`); nothing here is typed by hand. These tests
/// check what the app can check on its own: that each figure is the sum of its
/// shown working, that every card exists, that a worked combo never claims more
/// confidence than its lines, and that the Tabby to SIB chain is the one
/// surya described (3,600 - 360 - 199).
void main() {
  final combos = _json('assets/catalog/combos.json');
  final cards = {
    for (final c in (_json('assets/catalog/cards.json')['cards'] as List))
      (c as Map)['id'] as String: c,
  };
  final items = (combos['items'] as List).cast<Map<String, dynamic>>();

  test('combos.json is generated, not hand-edited', () {
    expect(combos['generated_by'], contains('export_app_combos.py'));
  });

  test('every card a combo names is in the bundled catalog', () {
    for (final i in items) {
      for (final id in (i['card_ids'] as List)) {
        expect(cards.keys, contains(id), reason: '${i['id']} names $id');
      }
    }
  });

  test('a saving figure is exactly the sum of its shown working', () {
    for (final i in items.where((i) => i['annual_saving_aed'] != null)) {
      final lines = (i['breakdown'] as List?)?.cast<Map<String, dynamic>>();
      expect(
        lines,
        isNotNull,
        reason: '${i['id']} has a figure with no working',
      );
      final sum = lines!.fold<double>(
        0,
        (a, l) => a + (l['yearly_aed'] as num).toDouble(),
      );
      expect(
        (i['annual_saving_aed'] as num).toDouble(),
        closeTo(sum, 0.01),
        reason: i['id'] as String,
      );
      expect(i['steps'], isNotEmpty, reason: '${i['id']} needs its steps');
    }
  });

  test(
    'a combo is never more confident than the weakest line of its working',
    () {
      for (final i in items.where((i) => i['breakdown'] != null)) {
        final weakest = (i['breakdown'] as List)
            .map((l) => (l as Map)['confidence'] as String)
            .any((c) => c == 'community' || c == 'unverified');
        if (weakest) {
          expect(i['confidence'], 'reported', reason: i['id'] as String);
        }
      }
    },
  );

  test(
    'the Tabby to SIB chain: 3,600 cashback, 360 Tabby fee, 199 SIB fee',
    () {
      final chain = items.firstWhere(
        (i) => i['id'] == 'reddit-tabby-sib-chain',
      );
      final lines = (chain['breakdown'] as List).cast<Map<String, dynamic>>();
      expect(
        {for (final l in lines) l['kind']: (l['yearly_aed'] as num).toDouble()},
        {'earn': 3600.0, 'fee': -360.0, 'annual_fee': -199.0},
      );
      expect(chain['annual_saving_aed'], 3041);
      // Paying the SIB bill with another card is shown but not counted.
      final steps = (chain['steps'] as List).cast<Map<String, dynamic>>();
      expect(steps.map((s) => s['counted']), [true, true, false]);
      // The mechanic is a chain, not four cards each taking a category.
      expect(chain['title'], isNot(contains('Dubai First')));
      // And the rates it uses are the catalog's own.
      final sib = cards['sib-cashback'] as Map;
      final rule = ((sib['reward_structure'] as Map)['rules'] as List)
          .cast<Map>()
          .firstWhere((r) => r['name'] == 'Online and wallet spend');
      expect(rule['rate'], 0.1);
      expect(rule['monthly_cap_units'], 300);
    },
  );

  test('the model reads steps, working and the server confidence wording', () {
    final parsed = parseCombos(
      File('assets/catalog/combos.json').readAsStringSync(),
      now: DateTime(2026, 11, 28),
    );
    final chain = parsed.firstWhere((c) => c.id == 'reddit-tabby-sib-chain');
    expect(chain.steps.length, 3);
    expect(chain.steps.last.counted, isFalse);
    expect(chain.breakdown.map((b) => b.yearlyAed), [3600, -360, -199]);
    expect(chain.confidenceLabel, contains('community'));
    expect(chain.annualSavingAed, 3041);
    expect(parsed.first.id, 'reddit-tabby-sib-chain'); // biggest saving first
  });
}
